mapper.select:
SELECT a.id, a.parking_lot_id, a.area_code, a.area_name, a.description, a.status, a.created_at, a.updated_at, (SELECT COUNT(*) FROM parking_space s WHERE s.area_id = a.id) AS space_count FROM parking_area a WHERE a.parking_lot_id = #{lotId}
AND a.status = #{status}
ORDER BY a.area_code

SELECT COUNT(*)
FROM parking_area
WHERE parking_lot_id = #{lotId}
  AND area_code = #{areaCode}

SELECT COUNT(*)
FROM parking_space
WHERE area_id = #{areaId}

SELECT status
FROM parking_lot
WHERE id = #{lotId}
